/* Keyboard accessibility refinement */
(() => {
  const dialog =
    document.querySelector("#project-dialog") ||
    document.querySelector("dialog");

  if (!dialog) return;

  const projectButtons = [...document.querySelectorAll(".project-open")];
  const closeButton =
    dialog.querySelector("#dialog-close") ||
    dialog.querySelector(".dialog-close") ||
    dialog.querySelector('[data-dialog-close]');

  const prevButton =
    dialog.querySelector("#gallery-prev") ||
    dialog.querySelector(".gallery-prev") ||
    dialog.querySelector('[data-gallery-prev]');

  const nextButton =
    dialog.querySelector("#gallery-next") ||
    dialog.querySelector(".gallery-next") ||
    dialog.querySelector('[data-gallery-next]');

  let opener = null;
  let keyboardOpening = false;

  const focusableSelector =
    'button:not([disabled]), a[href]:not([hidden]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

  function setKeyboardMode(enabled) {
    dialog.classList.toggle("keyboard-mode", enabled);
  }

  function focusDialog() {
    requestAnimationFrame(() => {
      if (!dialog.open) return;
      if (closeButton) {
        closeButton.focus();
      } else {
        dialog.setAttribute("tabindex", "-1");
        dialog.focus();
      }
    });
  }

  projectButtons.forEach((button) => {
    button.addEventListener("pointerdown", () => {
      opener = button;
      keyboardOpening = false;
      setKeyboardMode(false);
    });

    button.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;

      opener = button;
      keyboardOpening = true;
      setKeyboardMode(true);

      if (event.key === " ") {
        event.preventDefault();
        button.click();
      }

      focusDialog();
    });

    button.addEventListener("click", () => {
      if (!opener) opener = button;
      if (!keyboardOpening) setKeyboardMode(false);
      focusDialog();
    });
  });

  dialog.addEventListener("keydown", (event) => {
    if (!dialog.open) return;

    if (event.key === "Escape") {
      event.preventDefault();
      dialog.close();
      return;
    }


    if (event.key !== "Tab") return;

    const focusables = [...dialog.querySelectorAll(focusableSelector)]
      .filter((el) => !el.hidden && el.getClientRects().length > 0);

    if (!focusables.length) {
      event.preventDefault();
      dialog.focus();
      return;
    }

    const first = focusables[0];
    const last = focusables[focusables.length - 1];

    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  }, true);

  dialog.addEventListener("close", () => {
    setKeyboardMode(false);
    keyboardOpening = false;

    if (opener && document.contains(opener)) {
      opener.focus();
    }
    opener = null;
  });
})();
